CREATE TABLE "review_photos" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"review_id" uuid NOT NULL,
	"seq" integer NOT NULL,
	"storage_key" text,
	"storage_key_erased_at" timestamp with time zone,
	"content_type" text NOT NULL,
	"byte_size" bigint NOT NULL,
	"width" integer NOT NULL,
	"height" integer NOT NULL,
	"checksum_sha256" char(64) NOT NULL,
	"source_checksum_sha256" char(64) NOT NULL,
	"strip_recipe" text NOT NULL,
	"alt_text_th" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "review_photos_storage_key_unique" UNIQUE("storage_key"),
	CONSTRAINT "review_photos_review_seq_key" UNIQUE("review_id","seq"),
	CONSTRAINT "review_photos_seq_positive" CHECK ("review_photos"."seq" >= 1),
	CONSTRAINT "review_photos_content_type_supported" CHECK ("review_photos"."content_type" in ('image/jpeg', 'image/png', 'image/webp')),
	CONSTRAINT "review_photos_byte_size_positive" CHECK ("review_photos"."byte_size" > 0),
	CONSTRAINT "review_photos_dimensions_positive" CHECK ("review_photos"."width" > 0 and "review_photos"."height" > 0),
	CONSTRAINT "review_photos_checksum_hex" CHECK ("review_photos"."checksum_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "review_photos_source_checksum_hex" CHECK ("review_photos"."source_checksum_sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "review_photos_bytes_were_rewritten" CHECK ("review_photos"."checksum_sha256" <> "review_photos"."source_checksum_sha256"),
	CONSTRAINT "review_photos_strip_recipe_present" CHECK (btrim("review_photos"."strip_recipe") <> ''),
	CONSTRAINT "review_photos_erasure_shape" CHECK ("review_photos"."storage_key_erased_at" is null or "review_photos"."storage_key" is null)
);
